head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function() {
    var el = WebSquare.wUnit.getJq("#gv1_cell_0_3").find("td")[0];
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 name4항목의 값을 더블클릭하여 edit모드로 진입했을때 edit창의 높이와 이미지파일이 유지되는지 점검
    //1. After running the sample file, double-click the value of the name4 item to check whether the height of the edit window and the image file are maintained when entering edit mode
    //Verify step 1. The height of the edit window and the image file are maintained normally.(Previously the image disappears in chrome and in IE the height of the edit window increases)
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "scwin.check1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.check2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gv1__col4').css('width') == '41px'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'gv1__col4').style.width", "41px");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
