scwin.is_html5 = function() {
    if (document.doctype === null) {
        return false;
    }
    var node = document.doctype;
    var doctype_string = "<!DOCTYPE " + node.name + (node.publicId ? ' PUBLIC"' + node.publicId + '"' : '') + (!node.publicId && node.systemId ? ' SYSTEM' : '') + (node.systemId ? ' "' + node.systemId + '"' : '') + ">";
    return doctype_string === '<!DOCTYPE html>';
};
scwin.check1 = function() {
    var hh = scwin.is_html5() ? "23px" : "20px";

    if (document.getElementById('G_mf_gv1__col4').getBoundingClientRect().height % 1 == 0) {//디스플레이 배율 100%일때 체크
        return WebSquare.wUnit.getJq('#G_gv1__col4').css('height') === hh;
    } else {
        return true;
    }

    //return WebSquare.wUnit.getJq('#G_gv1__col4').css('height') === hh;
}
scwin.check2 = function() {
    var hh = scwin.is_html5() ? "23px" : "20px";
    return WebSquare.wUnit.getDomById('G_' + $p.id + 'gv1__col4').style.height === hh;
}
scwin.checkVal = function() {
    var imageSrc = WebSquare.wUnit.getDomById($p.id+'gv1_cell_1_3').getElementsByTagName('img')[0].getAttribute('src');
    if (imageSrc.indexOf('web5_test/SP2/2018/uiplugin/gridView/gridView_textImage_WEFF-98_(WSQ-3241).png') == -1) {
        return false;
    } else {
        return true;
    }
}
